+    assert_eq!(eval("print! \"A\""), successful_output("A\n"));
+    assert_eq!(
+        eval(r#"print! "    \{"b"}\{False} \{[1]}""#),
+        successful_output("    bFalse [1]\n")
+    );
+    assert_eq!(
+        eval(r#"print! "a\{"b"}c\{"d \{" e\{"f"}g\{-2+3}"}"}""#),
+        successful_output("abcd  efg1\n")
+    );
+    assert_eq!(
+        eval(
+            r#"print! """abc
+def
+  ghi
+j kl """"#
+        ),
+        successful_output("abc\ndef\n  ghi\nj kl \n")
+    );
+    assert_eq!(
+        eval(
+            r#"print! """
+  \{()}
+a
