+    await knex.raw(`USE test_sakila_${parallelId}`);
+  } catch (e) {
+    await knex.raw(`CREATE DATABASE test_sakila_${parallelId}`);
+    await knex.raw(`USE test_sakila_${parallelId}`);
+  }
+
